package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

// PrintASTStructure демонстрирует иерархию синтаксического дерева Go
func PrintASTStructure() {
	src := `
package sample

func Calculate(x int) int {
	if x > 0 {
		return x * 2
	}
	return 0
}
`
	fset := token.NewFileSet()
	node, err := parser.ParseFile(fset, "sample.go", src, parser.AllErrors)
	if err != nil {
		fmt.Println("Parse error:", err)
		return
	}

	fmt.Println("Имя пакета:", node.Name.Name)
	for _, decl := range node.Decls {
		if fn, ok := decl.(*ast.FuncDecl); ok {
			fmt.Printf("Объявление функции: %s\n", fn.Name.Name)
			fmt.Printf("  -> Параметров: %d\n", len(fn.Type.Params.List))
			fmt.Printf("  -> Операторов в теле: %d\n", len(fn.Body.List))
			for i, stmt := range fn.Body.List {
				switch s := stmt.(type) {
				case *ast.IfStmt:
					fmt.Printf("    [%d] Оператор условия: if ...\n", i)
				case *ast.ReturnStmt:
					fmt.Printf("    [%d] Оператор возврата: return ...\n", i)
				default:
					fmt.Printf("    [%d] Оператор типа: %T\n", i, s)
				}
			}
		}
	}
}

func main() {
	fmt.Println("=== Анатомия абстрактного синтаксического дерева (go/ast) ===")
	PrintASTStructure()
}

theory:
Синтаксическое дерево (AST) знает только то, что написано в коде: например, `x.Close()`. Но является ли `x` структурой `*os.File`, сетевым сокетом `net.Conn` или кастомным типом пользователя? Имеет ли метод `Close()` сигнатуру `Close() error` или не возвращает ничего?

Без информации о типах ответить на эти вопросы невозможно.

Пакет `go/types` выполняет полную проверку типов (Type Checking) по правилам языка Go и заполняет структуру `types.Info`:
1) **`Types map[ast.Expr]TypeAndValue`**: отображает любое синтаксическое выражение (например, `x + 1`) на его статический тип `types.Type` и значение (если вычисляется во время компиляции);
2) **`Defs map[*ast.Ident]Object`**: отображает идентификатор в месте его ОБЪЯВЛЕНИЯ на объект символа (переменная, константа, имя функции);
3) **`Uses map[*ast.Ident]Object`**: отображает идентификатор в месте его ИСПОЛЬЗОВАНИЯ на объект, где он был объявлен;
4) **`types.Implements(T, Iface)`**: позволяет программно проверить, реализует ли тип интерфейс `error` или `io.Closer`.

