package main

import (
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
)

// SemanticTypeAnalyzer демонстрирует извлечение типов компилятора через go/types
func SemanticTypeAnalyzer() {
	src := `
package main

import "io"

func CloseResource(r io.Closer) error {
	return r.Close()
}
`
	fset := token.NewFileSet()
	file, _ := parser.ParseFile(fset, "main.go", src, parser.AllErrors)

	// Настройка type checker
	conf := types.Config{Importer: importer.Default()}
	info := &types.Info{
		Types: make(map[ast.Expr]types.TypeAndValue),
		Defs:  make(map[*ast.Ident]types.Object),
		Uses:  make(map[*ast.Ident]types.Object),
	}

	pkg, err := conf.Check("main", fset, []*ast.File{file}, info)
	if err != nil {
		fmt.Println("Typecheck error:", err)
		return
	}

	fmt.Printf("Пакет успешно типизирован: %s\n", pkg.Path())
	fmt.Printf("Количество разрешенных выражений в Types: %d\n", len(info.Types))
	fmt.Printf("Количество определенных объектов в Defs: %d\n", len(info.Defs))
	fmt.Printf("Количество используемых объектов в Uses: %d\n", len(info.Uses))
}

func main() {
	fmt.Println("=== Семантический анализ типов с go/types ===")
	SemanticTypeAnalyzer()
}

theory:
Создание собственного линтера начинается с формулирования простого синтаксического инварианта.

В Go функция с пустым телом `func DoSomething() {}` часто является забытой заглушкой (TODO stub), ошибочно оставленной разработчиком в коде перед релизом.

Каноничная структура анализатора в терминах `go/analysis`:
```go
var Analyzer = &analysis.Analyzer{
    Name: "noempty",
    Doc:  "находит функции с пустым телом",
    Run:  run,
}

func run(pass *analysis.Pass) (interface{}, error) {
    for _, file := range pass.Files {
        // Обход AST
    }
    return nil, nil
}
```
Функция `run` итерируется по всем файлам пакета `pass.Files`, фильтрует объявления `*ast.FuncDecl` и сообщает об ошибках вызовом `pass.Reportf(fn.Pos(), "сообщение")`.

