package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

// DummyReport сообщение линтера
type DummyReport struct {
	Pos     token.Pos
	Message string
}

// CheckEmptyFunctions обходит AST и находит пустые функции
func CheckEmptyFunctions(fset *token.FileSet, file *ast.File) []DummyReport {
	var reports []DummyReport

	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			continue
		}

		// Если список операторов в теле функции пуст
		if len(fn.Body.List) == 0 {
			reports = append(reports, DummyReport{
				Pos:     fn.Pos(),
				Message: fmt.Sprintf("функция '%s' имеет пустое тело", fn.Name.Name),
			})
		}
	}

	return reports
}

func main() {
	fmt.Println("=== Создание первого статического анализатора (noempty) ===")
	src := `
package testpkg

func ValidFunction() {
	println("doing work")
}

func SuspiciousEmpty() {}
`
	fset := token.NewFileSet()
	file, _ := parser.ParseFile(fset, "test.go", src, 0)

	findings := CheckEmptyFunctions(fset, file)
	for _, f := range findings {
		pos := fset.Position(f.Pos)
		fmt.Printf("⚠️  [%s:%d] %s\n", pos.Filename, pos.Line, f.Message)
	}
}

theory:
Вместо ручного написания рекурсивных функций обхода десятков типов узлов `go/ast` предоставляет стандартную функцию высшего порядка `ast.Inspect`.

Сигнатура:
`ast.Inspect(node ast.Node, f func(ast.Node) bool)`

Механика работы:
1) Функция `f` вызывается для каждого узла дерева в порядке обхода в глубину (DFS — Depth-First Search);
2) Если `f` возвращает **`true`**, `ast.Inspect` продолжает спуск во всех потомков текущего узла;
3) Если `f` возвращает **`false`**, обход дочерних элементов этого узла прекращается (pruning subtrees). Это критически важно для производительности;
4) После того как все дети узла обойдены, функция `f` вызывается повторно со значением `n == nil`, что позволяет реализовать логику выхода из контекста (exit hook, аналог закрывающей скобки).

