package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

// RunInspectDemo демонстрирует рекурсивный обход AST функцией ast.Inspect
func RunInspectDemo() {
	src := `
package main

func Outer() {
	println("outer")
	fn := func() {
		println("inner closure")
	}
	fn()
}
`
	fset := token.NewFileSet()
	file, _ := parser.ParseFile(fset, "main.go", src, 0)

	totalNodes := 0
	callCount := 0

	// ast.Inspect рекурсивно обходит дерево в глубину (Depth-First Search)
	ast.Inspect(file, func(n ast.Node) bool {
		if n == nil {
			return false // Вызывается при выходе из узла
		}
		totalNodes++

		// Если встретили вызов функции
		if call, ok := n.(*ast.CallExpr); ok {
			callCount++
			pos := fset.Position(call.Pos())
			fmt.Printf("Найден вызов функции в строке %d\n", pos.Line)
		}

		// Возврат true означает: продолжать спускаться вглубь дочерних узлов
		// Возврат false остановил бы обход текущей подветки дерева!
		return true
	})

	fmt.Printf("Всего обойдено узлов AST: %d, вызовов функций: %d\n", totalNodes, callCount)
}

func main() {
	fmt.Println("=== Рекурсивный обход AST с помощью ast.Inspect ===")
	RunInspectDemo()
}

theory:
Для эффективности представления памяти компилятор Go не хранит строки и имена файлов в каждом синтаксическом узле AST. Вместо этого используется глобальная непрерывная числовая ось смещений — тип `token.Pos` (по сути, обычный `int`).

Структура `token.FileSet` управляет этой осью:
1) Каждый распарсенный файл занимает определенный диапазон смещений `[base, base + size]`;
2) Для любого `node.Pos()` метод `fset.Position(pos)` выполняет бинарный поиск по файлам и вычисляет:
   - `Filename string`: относительный или абсолютный путь к файлу;
   - `Line int`: точный номер строки (1-based);
   - `Column int`: номер символа в строке (1-based).

В `go/analysis` метод `pass.Reportf(node.Pos(), format, args...)` автоматически производит это преобразование и формирует диагностику `analysis.Diagnostic`.

