package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"strings"
)

// ImportPolicyValidator проверяет список разрешенных стандартных библиотек
type ImportPolicyValidator struct {
	allowedStdLib map[string]struct{}
}

func NewImportValidator() *ImportPolicyValidator {
	return &ImportPolicyValidator{
		allowedStdLib: map[string]struct{}{
			"context": {},
			"errors":  {},
			"fmt":     {},
			"time":    {},
			"strings": {},
		},
	}
}

func (v *ImportPolicyValidator) ValidateImports(fset *token.FileSet, file *ast.File) []string {
	var issues []string

	for _, imp := range file.Imports {
		path := strings.Trim(imp.Path.Value, `"`)

		// Если это сторонняя библиотека (содержит точку в первом сегменте домена)
		if strings.Contains(strings.Split(path, "/")[0], ".") {
			pos := fset.Position(imp.Pos())
			issues = append(issues, fmt.Sprintf("%s:%d: сторонняя библиотека '%s' запрещена в Core-пакете",
				pos.Filename, pos.Line, path))
			continue
		}

		// Проверка стандартной библиотеки по белому списку
		if _, ok := v.allowedStdLib[path]; !ok {
			pos := fset.Position(imp.Pos())
			issues = append(issues, fmt.Sprintf("%s:%d: пакет стандартной библиотеки '%s' не входит в разрешенный whitelist",
				pos.Filename, pos.Line, path))
		}
	}

	return issues
}

func main() {
	fmt.Println("=== Инспекция директив импорта (ast.ImportSpec) ===")
	src := `package core

import (
	"context"
	"net/http" // Запрещен whitelist'ом
	"github.com/google/uuid" // Сторонняя зависимость
)
`
	fset := token.NewFileSet()
	file, _ := parser.ParseFile(fset, "core/entity.go", src, 0)

	validator := NewImportValidator()
	findings := validator.ValidateImports(fset, file)
	for _, f := range findings {
		fmt.Println("🚨", f)
	}
}

theory:
Горутины в Go дешевы (около 2 КБ стека), что провоцирует разработчиков запускать их бесконтрольно: `go sendEmail()`, `go updateMetrics()`.

Три смертельных риска 'диких' горутин (Unguarded Goroutines):
1) **Необработанная паника**: Если внутри горутины произойдет `panic` (например, nil pointer dereference), аварийно завершится ВЕСЬ Go-процесс, положив весь сервис в Kubernetes;
2) **Утечка памяти и процессора (Goroutine Leak)**: Если горутина зависнет на вечном чтении небуферизованного канала или блокирующем сетевом сокете без таймаута, она останется в памяти навсегда;
3) **Нарушение Graceful Shutdown**: При остановке пода Kubernetes неконтролируемые горутины будут грубо убиты операционной системой на середине записи в базу данных.

Линтер `safego` запрещает прямое использование ключевого слова `go`, принуждая инженеров использовать безопасные обертки (например, `pool.Go()`, `errgroup.Group` или корпоративный `safego.Go(func())` с встроенным `recover()`).

