package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

// CheckUnguardedGoroutines находит 'дикие' запуски горутин без надзора
func CheckUnguardedGoroutines(fset *token.FileSet, file *ast.File) []string {
	var issues []string

	ast.Inspect(file, func(n ast.Node) bool {
		goStmt, ok := n.(*ast.GoStmt)
		if !ok {
			return true
		}

		pos := fset.Position(goStmt.Pos())
		// Проверяем, что именно запускается: анонимная функция go func() или обычная функция
		switch callTarget := goStmt.Call.Fun.(type) {
		case *ast.FuncLit:
			issues = append(issues, fmt.Sprintf("%s:%d: обнаружена неконтролируемая анонимная горутина 'go func()'; используйте WorkerPool или sync.WaitGroup",
				pos.Filename, pos.Line))
		case *ast.Ident:
			issues = append(issues, fmt.Sprintf("%s:%d: запуск горутины 'go %s()'; убедитесь в наличии graceful shutdown и recover",
				pos.Filename, pos.Line, callTarget.Name))
		default:
			issues = append(issues, fmt.Sprintf("%s:%d: неконтролируемый запуск горутины", pos.Filename, pos.Line))
		}

		return true
	})

	return issues
}

func main() {
	fmt.Println("=== Линтер safego: Детекция неконтролируемых горутин ===")
	src := `package handler

func HandleRequest() {
	// Опасный запуск без WaitGroup и отслеживания контекста!
	go func() {
		println("async work")
	}()
}
`
	fset := token.NewFileSet()
	file, _ := parser.ParseFile(fset, "handler.go", src, 0)

	findings := CheckUnguardedGoroutines(fset, file)
	for _, f := range findings {
		fmt.Println("🚨", f)
	}
}

theory:
В Go переменные, объявленные на уровне пакета через ключевое слово `var`, доступны всем горутинам и функциям этого пакета.

Почему глобальное состояние опасно:
1) **Гонки данных (Data Races)**: Если две горутины одновременно читают и пишут в `var GlobalConfig` или `var cache map[...]`, происходит повреждение памяти и аварийная остановка рантайма;
2) **Скрытые связи (Tight Coupling)**: Функции становятся нечистыми (Non-pure functions), их результат зависит от скрытого состояния, а не от переданных аргументов;
3) **Сложность тестирования**: Тесты, запущенные параллельно (`t.Parallel()`), начинают перезаписывать глобальные переменные друг друга, порождая плавающие падения (Flaky Tests).

Качественный линтер разрешает на уровне пакета только неизменяемые константы (`const`), статические ошибки (`var ErrNotFound = errors.New(...)`) и потокобезопасные синглтоны, запрещая изменяемые счетчики, мапы и срезы.

